"""Offline owned-build controls, using generated bytes and injected commands."""
import json
import os
from pathlib import Path
import subprocess
import tempfile
import unittest
from unittest.mock import patch
import mcp_runner_image_build as build
from mcp_runner_build_context import FILES,prepare_context,sha

class Build(unittest.TestCase):
 def thaw(self,root):
  root.chmod(0o700)
  for p in root.rglob('*'):
   if p.is_dir():p.chmod(0o700)
 def test_context_full_inventory_hash_modes(self):
  with tempfile.TemporaryDirectory() as temporary:
   root=Path(temporary).resolve();source=root/'source';source.mkdir();target=root/'prepared';target.mkdir(mode=0o700);hashes={}
   for name in FILES:
    p=source/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(name.encode());hashes[name]=sha(name.encode())
   result=prepare_context(source,target,hashes)
   try:
    build.validate_context(result['context'],result['manifest'],result['contextSha256'])
    p=Path(result['context'])/'index.js';p.chmod(0o644)
    with self.assertRaises(RuntimeError):build.validate_context(result['context'],result['manifest'],result['contextSha256'])
   finally:self.thaw(target)
 def test_handle_and_image_bindings(self):
  with tempfile.TemporaryDirectory() as temporary:
   p=Path(temporary).resolve()/'handle';p.write_text('123');p.chmod(0o600)
   self.assertEqual(build.read_owner_handle(p),123);p.chmod(0o644)
   with self.assertRaises(RuntimeError):build.read_owner_handle(p)
  image='sha256:'+'a'*64;tag='owned:tag';labels={'owner':'synthetic'}
  def command(_):return subprocess.CompletedProcess([],0,json.dumps([{'Id':image,'RepoTags':[tag],'Config':{'Labels':labels}}]),'')
  self.assertEqual(build.verify_built_image(command,image,tag,labels),image)
  with self.assertRaises(RuntimeError):build.verify_built_image(command,image,tag,{'owner':'foreign'})
 def exercise(self,failure):
  events=[]
  class Processes:
   def __init__(self,*a):pass
   def install(self):pass
   def mask_cleanup_signals(self):pass
   def restore(self):pass
   def launch(self,*a,**kwargs):
    events.append('launch')
    class Child:
     def wait(self,timeout):
      if failure=='timeout':raise subprocess.TimeoutExpired('controlled',timeout)
      return 1
    return Child()
   def finish(self,child):events.append('finish')
   def cleanup(self):events.append('cleanup')
  with tempfile.TemporaryDirectory() as temporary:
   root=Path(temporary).resolve();handle=root/'handle';handle.write_text('123');handle.chmod(0o600);evidence=root/'evidence';evidence.mkdir(mode=0o700)
   argv=['build']
   for name,value in {'docker-cli':'/controlled/docker','docker-cli-sha256':'a'*64,'docker-host':'unix:///controlled','docker-daemon-id':'owned','context':'/controlled/context','manifest':'/controlled/context-manifest.json','context-sha256':'b'*64,'evidence-root':str(evidence),'owner-handle-file':str(handle)}.items():argv.extend(['--'+name,value])
   with patch.object(build.sys,'argv',argv),patch.object(build,'validate_docker_cli',return_value='/controlled/docker'),patch.object(build,'validate_context',side_effect=lambda *a:events.append('validate')),patch.object(build,'prepare_evidence_root',return_value=evidence),patch.object(build,'verify_daemon'),patch.object(build,'OwnedProcesses',Processes),patch.object(build.subprocess,'run',return_value=subprocess.CompletedProcess([],0,'','')):
    with self.assertRaises((RuntimeError,subprocess.TimeoutExpired)):build.main()
   terminal=json.loads((evidence/'terminal.json').read_text());self.assertEqual(terminal['status'],'failed')
   self.assertEqual(events.count('validate'),2);self.assertIn('cleanup',events);self.assertIn('finish',events)
   self.assertEqual(terminal['imageCleanup'],'retained_for_root_verification')
 def test_failed_build_preserves_evidence(self):self.exercise('nonzero')
 def test_timeout_cleans_owned_builder_and_postflights(self):self.exercise('timeout')
if __name__=='__main__':unittest.main()
